package com.sunrise.dentalclinic.service;
import com.sunrise.dentalclinic.exception.BusinessException;import com.sunrise.dentalclinic.model.*;import com.sunrise.dentalclinic.repository.BillRepository;import org.junit.jupiter.api.*;import java.math.BigDecimal;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class BillingServiceTest{BillRepository repo=mock(BillRepository.class);AppointmentService appointments=mock(AppointmentService.class);BillingService service=new BillingService(repo,appointments,new BigDecimal("1000.00"));
 @Test void calculatesBillTotalWithCurrencyScale(){assertEquals(new BigDecimal("3500.50"),service.calculateTotal(new BigDecimal("2500.5"),new BigDecimal("1000")));}
 @Test void preventsDuplicateBill(){var a=new Appointment();when(appointments.byNumber("APT-1")).thenReturn(a);when(repo.existsByAppointmentId(a.getId())).thenReturn(true);assertThrows(BusinessException.class,()->service.generate("APT-1"));}
 @Test void preventsBillingCancelledAppointment(){var a=new Appointment();a.setStatus(AppointmentStatus.CANCELLED);when(appointments.get(7L)).thenReturn(a);var error=assertThrows(BusinessException.class,()->service.generate(7L));assertEquals("Cancelled appointments cannot be billed",error.getMessage());}}
